def log(self, from_commit: str, to_commit: str) -> list[str]:
    if self.hgclient:
        return [
            rev.desc.decode("utf-8")
            for rev in self.hgclient.log(f"{to_commit} % {from_commit}")
        ]
    else:
        return (
            git(
                self.root,
                "log",
                "--pretty=format:%s",
                f"{from_commit}..{to_commit}",
            )
            .strip()
            .splitlines()
